import {FormDialog, FormDialogField} from "@corensystem/core-ui/form-dialog";

<FormDialog
	open={open}
	onOpenChange={setOpen}
	title="Create process"
	valid={name.trim().length > 0}
	hint="Name it, then create."
	error="Name required."
	submitLabel="Create process"
	onSubmit={() => onCreate({name: name.trim()})}
	onReset={() => setName("")}
>
	<FormDialogField label="Name" invalid={name.trim().length === 0}>
		{({invalid}) => <Input value={name} aria-invalid={invalid} onChange={(e) => setName(e.target.value)} />}
	</FormDialogField>
</FormDialog>
